void counting_sort(const int in[], int out[], int n, int k) {
  int *count = calloc(k + 1, sizeof *count);
  for (int i = 0; i < n; i++) count[in[i]]++;
  for (int v = 1; v <= k; v++) count[v] += count[v - 1];
  for (int i = n - 1; i >= 0; i--) out[--count[in[i]]] = in[i];   // right to left = stable
  free(count);
}
